import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class PermutationGenerator {

    public List<List<Integer>> permute(int[] nums) {
        // Copy the input array to avoid modifying the original array
        int[] current = new int[nums.length];
        System.arraycopy(nums, 0, current, 0, nums.length);
        List<List<Integer>> result = new ArrayList<>();
        backtracking(current, result, 0);
        return result;
    }

    private void backtracking(int[] current, List<List<Integer>> result, int start) {
        if (start == current.length) {
            result.add(new ArrayList<>(Arrays.asList(current)));
            return;
        }

        for (int i = start; i < current.length; i++) {
            swap(current, start, i);
            backtracking(current, result, start + 1);
            swap(current, start, i); // backtrack
        }
    }

    private void swap(int[] array, int i, int j) {
        int temp = array[i];
        array[i] = array[j];
        array[j] = temp;
    }
}
