import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;

public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    ArrayDeque<Integer> stack = new ArrayDeque<>(Arrays.asList(nums));
    backtrackRecursive(result, stack);
    return result;
}

private void backtrackRecursive(List<List<Integer>> result, ArrayDeque<Integer> stack) {
    if (stack.isEmpty()) {
        result.add(new ArrayList<>(stack));
        return;
    }

    for (int i = 0; i < stack.size(); i++) {
        Collections.swap(stack, i, stack.size() - 1);
        backtrackRecursive(result, stack);
        Collections.swap(stack, i, stack.size() - 1);
    }
}
