private void permuteHelper(int[] numbers, List<Integer> current, List<List<Integer>> results) {
    if (numbers.length == current.size()) {
        results.add(new ArrayList<>(current));
        return;
    }

    for (int i = 0; i < numbers.length; i++) {
        if (!current.contains(numbers[i])) {
            current.add(numbers[i]);
            permuteHelper(numbers, current, results);
            current.remove(current.size() - 1);
        }
