public static int countOilDeposits(char[][] grid) {
    HashSet<String> visited = new HashSet<>();
    int count = 0;

    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[i].length; j++) {
            if (grid[i][j] == '@' && !visited.contains(i + "," + j)) {
                dfs(grid, i, j, visited);
                count++;
            }
        }
    }

    return count;
}

private static void dfs(char[][] grid, int x, int y, HashSet<String> visited) {
    if (x < 0 || x >= grid.length || y < 0 || y >= grid[x].length || grid[x][y] == '*') return;

    if (visited.contains(x + "," + y)) return;

    visited.add(x + "," + y);

    dfs(grid, x + 1, y, visited);
    dfs(grid, x - 1, y, visited);
    dfs(grid, x, y + 1, visited);
    dfs(grid, x, y - 1, visited);
}
