public static int countOilDeposits(char[][] grid) {
    Set<String> uniqueDeposits = new HashSet<>();
    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[i].length; j++) {
            if (grid[i][j] == '@') {
                String deposit = generateDeposit(i, j, grid);
                uniqueDeposits.add(deposit);
            }
        }
    }
    return uniqueDeposits.size();
}

private static String generateDeposit(int i, int j, char[][] grid) {
    StringBuilder deposit = new StringBuilder();
    char[][] visited = new char[grid.length][grid[0].length];
    for (int ni = i - 1; ni <= i + 1; ni++) {
        for (int nj = j - 1; nj <= j + 1; nj++) {
            if (ni >= 0 && ni < grid.length && nj >= 0 && nj < grid[0].length && grid[ni][nj] == '*' && !visited[ni][nj]) {
                deposit.append('*');
                visited[ni][nj] = true;
                deposit.append(generateDeposit(ni, nj, grid));
            }
        }
    }
    return deposit.length() > 0 ? deposit.toString() : "*";
}
