/**
 * Counts the distinct oil deposits in the given grid.
 * 
 * @param grid the grid representing the land with oil pockets
 * @return the number of distinct oil deposits
 */
public static int countOilDeposits(char[][] grid) {
    int count = 0;
    for (char[] row : grid) {
        for (char cell : row) {
            if (cell == '@') {
                count++;
                deleteRowAndColumn(grid, row, cell); // Delete the row and column for the oil deposit
            }
        }
    }
    return count;
}

/**
 * Deletes the specified row and column from the grid.
 * 
 * @param grid the grid to modify
 * @param row the row to delete
 * @param cell the character in the row to delete
 */
private static void deleteRowAndColumn(char[][] grid, char[] row, char cell) {
    for (int i = 0; i < grid.length; i++) {
        if (grid[i][row.indexOf(cell)] != ' ') {
            grid[i][row.indexOf(cell)] = ' ';
        }
    }
    grid[row.indexOf(cell)] = row[0];
}

