public static int countOilDeposits(char[][] grid) {
    int count = 0;
    for (char[] row : grid) {
        for (char c : row) {
            if (c == '@') {
                count++;
                floodFill(grid, c, 0, 0);
            }
        }
    }
    return count;
}

private static void floodFill(char[][] grid, char target, int x, int y) {
    if (x < 0 || y < 0 || x >= grid.length || y >= grid[0].length || grid[x][y] != target) {
        return;
    }
    grid[x][y] = '#'; // Mark as visited
    floodFill(grid, target, x + 1, y);
    floodFill(grid, target, x - 1, y);
    floodFill(grid, target, x, y + 1);
    floodFill(grid, target, x, y - 1);
}
