    public static int countOilDeposits(char[][] grid) {
        if (grid == null || grid.length == 0 || grid[0].length == 0)
            throw new IllegalArgumentException("Input grid must be non-null and non-empty");

        Set<String> oilDeposits = new HashSet<>();
        int rows = grid.length;
        int cols = grid[0].length;
        int sum = 0;

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*') {
                    rowFlag = new boolean[rows];
                    colFlag = new boolean[cols];
                    sum = 1;
                    helper(grid, i, j, rowFlag, colFlag);
                    oilDeposits.add(sum + "");
                }
            }
        }

        return oilDeposits.size();
    }

    private static boolean[] rowFlag;
    private static boolean[] colFlag;

    private static void helper(char[][] grid, int r, int c, boolean[] row, boolean[] col) {
        if (r < 0 || r >= grid.length || c < 0 || c >= grid[0].length || grid[r][c] == '*' || row[r] || col[c])
            return;

        row[r] = true;
        col[c] = true;
        sum++;

        helper(grid, r + 1, c, row, col);
        helper(grid, r - 1, c, row, col);
        helper(grid, r, c + 1, row, col);
        helper(grid, r, c - 1, row, col);
    }
}
