 */
public static int countDoubles(int[] numbers) {
    Map<Integer, Integer> numberCounts = new HashMap<>();
    int count = 0;

    // Count the occurrences of each number
    for (int num : numbers) {
        numberCounts.put(num, numberCounts.getOrDefault(num, 0) + 1);
    }

    // check how many numbers are twice an existing number
    for (int num : numbers) {
        if (numberCounts.containsKey(num * 2)) {
            count += numberCounts.get(num);
        }
    }

    return count;
