public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (start == null || end == null || n <= 0 || paths == null || paths.length < n) {
        return "Invalid input";
    }

    boolean[] visited = new boolean[n];
    boolean[][] visitedPaths = new boolean[n][n];

    if (isDirectPath(paths, start, end)) {
        return "can be travelled";
    }

    dfs(start, end, visited, visitedPaths);

    if (visited[end]) {
        return "can be travelled";
    }

    return "cannot be travelled";
}

private boolean isDirectPath(int[][] paths, int[] start, int[] end) {
    for (int i = 0; i < paths.length; i++) {
        if (paths[i][start[0]] == end[1] && paths[i][start[1]] == end[0]) {
            return true;
        }
    }
    return false;
}

private boolean dfs(int[] current, int[] end, boolean[] visited, boolean[][] visitedPaths) {
    visited[current[0]] = true;
    visitedPaths[current[0]][current[1]] = true;

    for (int i = 0; i < 4; i++) {
        int[] next = getNextStep(current, i);
        if (next == null) {
            continue;
        }

        if (next == end) {
            return true;
        }

        if (!visited[next[0]]) {
            if (dfs(next, end, visited, visitedPaths)) {
                return true;
            }
        }
    }

    visited[next[0]] = false;
    visitedPaths[next[0]][next[1]] = false;
    return false;
}

private int[] getNextStep(int[] current, int direction) {
    int[][] directions = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};
    int[] next = new int[]{current[0] + directions[direction][0], current[1] + directions[direction][1]};
    if (next[0] < 0 || next[0] >= 4 || next[1] < 0 || next[1] >= 4) {
        return null;
    }
    return next;
}
