public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n == 0) {
        return "cannot be travelled";
    }

    Set<Integer> visited = new HashSet<>();
    boolean canReachEnd = hasRoute(paths, start, end, visited, 0);

    return canReachEnd ? "can be travelled" : "cannot be travelled";
}

private static boolean hasRoute(int[][] paths, int[] start, int[] end, Set<Integer> visited, int step) {
    // If the initial position is the same as the end position, we have found a route
    if (Arrays.equals(start, end)) {
        return true;
    }

    if (visited.contains(step)) {
        return false;
    }

    visited.add(step);

    // Explore all possible moves from the current step
    for (int[] path : paths) {
        if (path[0] == step && hasRoute(paths, path, end, visited, step + 1)) {
            return true;
        }
    }

    return false;
}
