public static String appx(String word1, String word2) {
    int numCommonLetters = countCommonLetters(word1, word2);
    int sumLengths = word1.length() + word2.length();
    int gcd = greatestCommonDivisor(numCommonLetters, sumLengths);

    int reducedNumerator = numCommonLetters / gcd;
    int reducedDenominator = sumLengths / gcd;

    return "appx(" + word1 + ", " + word2 + ") = " + reducedNumerator + "/" + reducedDenominator;
}

private static int countCommonLetters(String word1, String word2) {
    int[] count1 = new int[26];
    int[] count2 = new int[26];

    for (char c : word1.toCharArray()) {
        count1[c - 'a']++;
    }

    for (char c : word2.toCharArray()) {
        count2[c - 'a']++;
    }

    int commonCount = 0;
    for (int i = 0; i < 26; i++) {
        commonCount += Math.min(count1[i], count2[i]);
    }

    return commonCount;
}

private static int greatestCommonDivisor(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}
