public boolean canArrange(int[] arr, int k) {
    Arrays.sort(arr);
    int requiredSum = 0;
    for (int i = 0; i < arr.length; i++) {
        requiredSum += arr[i];
        requiredSum %= k;
        if (requiredSum == 0) {
            continue;
        }
        int complement = requiredSum;
        if (complement < 0) {
            complement += k;
        }
        if (complement < arr[i]) {
            return false;
        }
        int j = Arrays.binarySearch(arr, complement);
        if (j > i) {
            return true;
        }
    }
    return false;
