        while (left < right) {
            int currentSum = arr[left] + arr[right];
            if (currentSum % k == 0) {
                left++;
                right--;
            } else if (currentSum % k < 0) {
                currentSum += k;
                right--;
            } else {
                left++;
            }
        }
        return left >= right;
    }

    public static void main(String[] args) {
        ArrayPartitionProblem problem = new ArrayPartitionProblem();
        // Test cases
        System.out.println(problem.canArrange(new int[]{1, 2, 3, 4, 5, 10, 6, 7, 8, 9}, 5)); // Output: true
        System.out.println(problem.canArrange(new int[]{1, 2, 3, 4, 5, 6}, 7)); // Output: true
        System.out.println(problem.canArrange(new int[]{1, 2, 3, 4, 5, 6}, 10)); // Output: false
    }
}
