public boolean canArrange(int[] arr, int k) {
    HashMap<Integer, Integer> modCount = new HashMap<>();
    int n = arr.length;
    for (int num : arr) {
        modCount.put(num % k, modCount.getOrDefault(num % k, 0) + 1);
    }

    for (int i = 1; i <= k / 2; i++) {
        if (modCount.containsKey(i) && modCount.containsKey(k - i)) {
            if (modCount.get(i) != modCount.get(k - i)) {
                return false;
            }
        } else if (i != k / 2) {
            return false;
        }
    }
    return true;
}
