/**
 * Calculates the minimum time required to collect all apples and return to node 0.
 *
 * @param n     the number of nodes in the tree
 * @param edges the list of edges in the tree
 * @param hasApple an array indicating whether each node has an apple
 * @return the minimum time required
 */
public class MinTime {
    private int time;

    public MinTime() {
        this.time = 0;
    }

    public int minTime(int n, int[][] edges, boolean[] hasApple) {
        // Create an adjacency list representation of the tree
        List<List<Integer>> adj = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }

        // Build the adjacency list from the edges
        for (int[] edge : edges) {
            adj.get(edge[0])..add(edge[1]);
            adj.get(edge[1]).add(edge[0]);
        }

        // Perform a depth-first search to calculate the time to collect all apples
        dfs(adj, 0, hasApple);
        return time;
    }

    /**
     * Recursive depth-first search function to calculate the time to collect all apples.
     *
     * @param adj      the adjacency list representation of the tree
     * @param current  the current node being processed
     * @param hasApple an array indicating whether each node has an apple
     * @return the time required to collect the apples from the current node to the root
     */
    private int dfs(List<List<Integer>> adj, int current, boolean[] hasApple) {
        time++; // Increment the time by 1 to account for the visit to the current node

        int timeToCollect = 0;
        for (int neighbor : adj.get(current)) {
            if (!hasApple[neighbor] || neighbor == current) {
                continue; // Skip visiting apple nodes or the current node itself
            }
            timeToCollect = Math.max(timeToCollect, dfs(adj, neighbor, hasApple)); // Recursively calculate time to collect apples from the neighbor
        }

        if ((hasApple[current] && timeToCollect == 0) || (timeToCollect > 0)) {
            time++; // Increment the time by 1 to account for the return from the current node to the root
            return time + timeToCollect; // Add the time to collect apples from the neighbor to the total time
        }

        return 0; // Return 0 if no apples are found from the neighbor
    }
}
