import java.util.*;

public class StringSorter {
    public String sortString(String s) {
        if (s == null || s.isEmpty()) {
            return "";
        }

        PriorityQueue<Character> minHeap = new PriorityQueue<>();
        PriorityQueue<Character> maxHeap = new PriorityQueue<>(Collections.reverseOrder());
        HashMap<Character, Integer> charCountMap = new HashMap<>();
        List<Character> result = new ArrayList<>();

        // Build heaps and count occurrences of each character
        for (char c : s.toCharArray()) {
            if (!charCountMap.containsKey(c)) {
                charCountMap.put(c, 0);
            }
            charCountMap.put(c, charCountMap.get(c) + 1);

            minHeap.offer(c);
            maxHeap.offer(c);
        }

        // Repeatedly pick characters based on the requirements
        while (!minHeap.isEmpty()) {
            char minChar = minHeap.poll();
            result.add(minChar);
            if (charCountMap.get(minChar) > 1) {
                charCountMap.put(minChar, charCountMap.get(minChar) - 1);
                minHeap.offer(minChar);
            } else {
                minHeap.poll();
            }
        }

        while (!maxHeap.isEmpty()) {
            char maxChar = maxHeap.poll();
            result.add(maxChar);
            if (charCountMap.get(maxChar) > 1) {
                charCountMap.put(maxChar, charCountMap.get(maxChar) - 1);
                maxHeap.offer(maxChar);
            } else {
                maxHeap.poll();
            }
        }

        return new StringBuilder(result).toString();
    }

    public static void main(String[] args) {
        StringSorter sorter = new StringSorter();
        System.out.println(sorter.sortString("cbaaedcb"));
        // Expected output: "aaabcedc"
    }
}
