import java.util.Arrays;

public class ArraySplitChecker {
    /**
     * Checks if it is possible to split the given integer array into two non-empty arrays
     * with the same average.
     *
     * @param nums The array of integers to check.
     * @return true if it is possible to split the array with the same average, false otherwise.
     */
    public static boolean splitArraySameAverage(int[] nums) {
        int totalSum = Arrays.stream(nums).sum();
        int length = nums.length;
        if (totalSum % 2 != 0) {
            return false;
        }
        int targetSum = totalSum / 2;

        for (int i = 1; i <= length / 2; i++) {
            if (generateSubarray(nums, i, 0, 0, targetSum)) {
                return true;
            }
        }
        return false;
    }

    private static boolean generateSubarray(int[] nums, int size, int start, int sum, int target) {
        if (size == 0) {
            return sum == target;
        }
        if (sum > target || target < sum - nums[start]) {
            return false;
        }
        return generateSubarray(nums, size - 1, start + 1, sum + nums[start], target) ||
               generateSubarray(nums, size, start + 1, sum, target - nums[start]);
    }

    public static void main(String[] args) {
        // Test cases
        System.out.println(splitArraySameAverage(new int[]{1, 2, 3, 4, 5, 6, 7, 8})); // Expected output: true
        System.out.println(splitArraySameAverage(new int[]{3, 1})); // Expected output: false
    }
}
