private boolean checkArray(int[] nums, int index, int sum, int k, int split, boolean[] visited) {
    if (index == nums.length) {
        return split <= k;
    }
    if (visited[index]) {
        return false;
    }
    visited[index] = true;
    boolean result = checkArray(nums, index + 1, sum - nums[index], k, split, visited) || checkArray(nums, index + 1, sum, k, split - 1, visited);
    visited[index] = false;
    return result;
}

private int totalSum(int[] nums) {
    int sum = 0;
    for (int num : nums) {
        sum += num;
