public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length <= 1) {
        return false;
    }

    int totalSum = Arrays.stream(nums).sum();
    int targetSum = totalSum / (int) Math.ceil((double) nums.length / 2);

    return findSubarraySum(nums, 0, nums.length - 1, targetSum);
}

private boolean findSubarraySum(int[] nums, int start, int end, int target) {
    if (start >= end && target == 0) {
        return true;
    }

    for (int i = start; i <= end; i++) {
        if (nums[i] == target) {
            return true;
        }
        if (target > numbers[i]) {
            if (findSubarraySum(nums, start, i - 1, target - numbers[i])) {
                return true;
            }
        }
    }
    return false;
}
