public boolean hasAllCodes(String s, int k) {
    // Initialize a mask with all 0s.
    // Each bit represents a binary string of length k.
    // If a bit is set, it means the corresponding binary string of length k is found in s.
    int mask = (1 << k) - 1;
    // Use an array to keep track of the states of k-1-bit sequences.
    int[] states = new int[1 << (k - 1)];
    // Mark the first sequence as found.
    states[0] = 1;

    for (int i = 0; i < s.length(); i++) {
        // Get the current sequence bits.
        int current = states[(i &(mask)) >> (k - 1)];
        // Shift the current sequence bits to the left by 1.
        current = current << 1;
        // Update the current sequence bits.
        current |= (s.charAt(i) - '0');
        // Mark the current sequence as found.
        states[current] = 1;
    }

    // If all states are set to 1, all binary strings of length k are found in s.
    for (int i = 0; i < states.length; i++) {
        if (states[i] == 0) return false;
    }

    return true;
}
