public class StringHasAllCodes {
    public boolean hasAllCodes(String s, int k) {
        Set<String> substringSet = new HashSet<>();

        // Get the substrings of length k
        for (int i = 0; i <= s.length() - k; i++) {
            substringSet.add(s.substring(i, i + k));
        }

        // Check if all possible substrings of length k are present in the set
        for (int length = 0; length <= k; length++) {
            for (int i = 0; i < Math.pow(2, length); i++) {
                String substring = Integer.toBinaryString(i).substring(0, length);
                if (!substringSet.contains(substring)) {
                    return false;
                }
            }
        }

        // If all possible substrings of length k are present, return true
        return true;
    }

