public boolean hasAllCodes(String s, int k) {
    if (k == 1) return true; // Single character is always a substring of any string

    int maxLength = s.length() - k + 1; // Possible total length of substrings
    boolean[] substringCount = new boolean[maxLength]; // Track presence of each substring

    for (int i = 0; i < maxLength; i++) {
        String substring = s.substring(i, i + k);
        substringCount[Integer.parseInt(substring, 2)] = true;
    }

    // Check if all substrings from 0 to maxLength-1 appear exactly once
    for (boolean count : substringCount) {
        if (!count) return false;
    }

    return true;
}
