            char c = s.charAt(i);
            if (c == '(') {
                stack.push(c);
            } else {
                if (stack.isEmpty()) {
                    unbalancedCount++;
                } else {
                    stack.pop();
                }
            }
        }

        return unbalancedCount + stack.size();
    }

