public int minOperations(int n) {
    int sum = n * n;
    int result = 0;

    if (n % 2 == 0) {
        sum -= n;
        n--;
        while (n > 0) {
            result += 2 - n;
            sum -= 2;
            n -= 2;
        }
    } else {
        sum -= n;
        while (n > 0) {
            result += 2 - n;
            sum -= 2;
            n -= 2;
        }
    }

