public int maxAbsoluteSum(int[] nums) {
    int maxSubarraySum = Integer.MIN_VALUE;
    int minSubarraySum = Integer.MAX_VALUE;

    // Find the maximum sum of any subarray using Kadane's Algorithm
    int currentMax = 0;
    int currentMin = 0;
    for (int num : nums) {
        currentMax = Math.max(num, currentMax + num);
        currentMin = Math.min(num, currentMin + num);
        maxSubarraySum = Math.max(maxSubarraySum, currentMax);
        minSubarraySum = Math.min(minSubarraySum, currentMin);
    }

    // The maximum absolute sum is the maximum of the absolute difference
    // between maxSubarraySum and minSubarraySum
    return Math.max(maxSubarraySum - minSubarraySum, -(maxSubarraySum - minSubarraySum));
}
