import java.util.ArrayList;

public class MinFibonacciNumbers {

    /**
     * Finds the minimum number of Fibonacci numbers that sum up to the given integer.
     *
     * @param k the integer to be represented by Fibonacci numbers
     * @return the minimum number of Fibonacci numbers that sum up to k
     */
    public int findMinFibonacciNumbers(int k) {
        ArrayList<Integer> fibonacciNumbers = new ArrayList<>();
        fibonacciNumbers.add(0);
        fibonacciNumbers.add(1);

        int nextFib = fibonacciNumbers.get(fibonacciNumbers.size() - 1) + fibonacciNumbers.get(fibonacciNumbers.size() - 2);
        while (nextFib <= k) {
            fibonacciNumbers.add(nextFib);
            nextFib = fibonacciNumbers.get(fibonacciNumbers.size() - 1) + fibonacciNumbers.get(fibonacciNumbers.size() - 2);
        }

        int count = 0;
        while (k > 0) {
            int maxFib = fibonacciNumbers.get(fibonacciNumbers.size() - 1);
            while (maxFib > k) {
                maxFib = fibonacciNumbers.get(fibonacciNumbers.size() - 2);
                count++;
            }
            if (maxFib == k) {
                count++;
                break;
            }
            k -= maxFib;
            count++;
        }

        return count;
    }
}
