public class FibonacciMinSum {
    public static void main(String[] args) {
        // Test cases to verify the solution
        System.out.println(findMinFibonacciNumbers(7));  // Output: 2
        System.out.println(findMinFibonacciNumbers(10)); // Output: 2
        System.out.println(findMinFibonacciNumbers(19)); // Output: 3
    }

    /**
     * Finds the minimum number of Fibonacci numbers whose sum is equal to k.
     *
     * @param k the target sum
     * @return the minimum number of Fibonacci numbers
     */
    public static int findMinFibonacciNumbers(int k) {
        if (k <= 2)
            return k;

        ArrayList<Integer> fibSequence = new ArrayList<>();
        generateFibonacciSequence(fibSequence, 1, 1);

        int count = 0;
        for (int i = fibSequence.size() - 1; i >= 0; i--) {
            while (k - fibSequence.get(i) >= 0) {
                k -= fibSequence.get(i);
                count++;
            }
            if (k == 0) {
                return count;
            }
        }
        return -1;
    }

    /**
     * Generates the Fibonacci sequence.
     *
     * @param sequence the ArrayList to store Fibonacci numbers
     * @param a the first number in the sequence
     * @param b the second number in the sequence
     */
    private static void generateFibonacciSequence(ArrayList<Integer> sequence, int a, int b) {
        sequence.add(a);
        while (b <= Integer.MAX_VALUE - a) {
            int next = a + b;
            sequence.add(next);
            a = b;
            b = next;
        }
    }
}
