    public static void main(String[] args) {
        System.out.println("Kth Factor of 12: " + kthFactor(12, 3)); // Expected output: 3
        System.out.println("Kth Factor of 7: " + kthFactor(7, 2)); // Expected output: 7
        System.out.println("Kth Factor of 4: " + kthFactor(4, 4)); // Expected output: -1
    }

    /**
     * Finds and returns the kth factor of n.
     *
     * @param n the number to find the factor for
     * @param k the kth factor to find
     * @return the kth factor, or -1 if n has less than k factors
     */
    public static int kthFactor(int n, int k) {
        ArrayList<Integer> factors = new ArrayList<>();

        // Find all factors of n
        for (int i = 1; i * i <= n; i++) {
            if (n % i == 0) {
                factors.add(i);
                if (i != n / i) {
                    factors.add(n / i);
                }
            }
        }

        // Sort the factors in ascending order
        Collections.sort(factors);

        // Return the kth factor or -1 if there are fewer than k factors
        if (factors.size() < k) {
            return -1;
        } else {
            return factors.get(k - 1);
        }
    }
}
