public int maxUniqueSplit(String s) {
    int n = s.length();
    if (n <= 1) {
        return n;
    }

    int[] indices = new int[26];
    Arrays.fill(indices, -1);
    char[] chars = s.toCharArray();

    int result = 1;
    Stack<Integer> stack = new Stack<>();
    for (int i = 0; i < n; i++) {
        int index = chars[i] - 'a';

        if (indices[index] != -1) {
            // Pop characters from the stack until the current index is the second latest index of the current character
            while (!stack.isEmpty() && stack.peek() <= indices[index]) {
                stack.pop();
            }
        }

        // If the stack is empty or the current index is the second latest index of the current character, add it to the stack
        if (stack.isEmpty() || stack.peek() == indices[index] - 1) {
            stack.push(i);
        }

        // Update the result if the current position is still within the bounds
        if (i + 1 < n) {
            result = Math.max(result, stack.size());
        }
    }

    return result;
}
