public class StringGenerator {

    public static String getSmallestString(int n, int k) {
        // If k is at least as large as the sum of n plus the largest possible letter,
        if (k >= (1 + 'z') * n) {
            return new String(new char[n], 0, n - 1) + 'a';
        }

        char[] smallest = new char[n];
        HashSet<Character> charSet = new HashSet<>();

        // Start with the smallest possible value (a) and build the string
        for (int i = 0; i < n; i++) {
            smallest[i] = 'a';
            charSet.add('a');
        }

        // Fill up the string with the next possible values
        int remainingK = k;
        for (int i = 0; i < n; i++) {
            if (remainingK <= 0) {
                break;
            }
            smallest[i]++;
            if (smallest[i] > 'z') {
                smallest[i] = 'a';
                remainingK--;
            }
            charSet.add(smallest[i]);
        }

        return new String(smallest);
    }

    public static void main(String[] args) {
        System.out.println(getSmallestString(3, 27)); // Output: "aay"
        System.out.println(getSmallestString(5, 73)); // Output: "aaszz"
    }
}
