    int maxLength = 0;
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (mat[i][j] == 1) {
                // Update the length of the current line in each direction:
                dp[0] = (j > 0) ? dp[0] + 1 : 1;
                dp[1] = (i > 0) ? dp[1] + 1 : 1;
                dp[2] = (i > 0 && j > 0) ? dp[2] + 1 : 1;
                dp[3] = (i < rows - 1 && j < cols - 1) ? dp[3] + 1 : 1;

                maxLength = Math.max(maxLength, Math.max(Math.max(dp[0], dp[1]), Math.max(dp[2], dp[3])));
            } else {
                // Reset the direction arrays for the next line:
                Arrays.fill(dp, 0);
            }
        }
    }

    return maxLength;
