public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0)
        return 0;
    int res = 0;
    boolean[] isVisited = new boolean[n];
    arrayToSquarePerm(A, res, 0, isVisited);
    return res;
}

private static void arrayToSquarePerm(int[] A, int res, int i, boolean[] isVisited) {
    if (i == A.length) {
        res++;
        return;
    }
    for (int j = 0; j < A.length; j++) {
        if (!isVisited[j] && isValid(A, i, j)) {
            isVisited[j] = true;
            arrayToSquarePerm(A, res, i + 1, isVisited);
            isVisited[j] = false;
        }
    }
}

private static boolean isValid(int[] A, int i, int j) {
    int sum = A[i] + A[j];
    int sqrt = (int) Math.sqrt(sum);
    return sqrt * sqrt == sum;
}
