public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 1) {
        return A[0] == 1 ? 1 : 0;
    }

    int count = 0;
    int[] remaining = new int[n - 1];
    int[] indices = new int[n];

    for (int i = 0; i < n; i++) {
        indices[i] = i;
    }

    squarePermutations(remaining, indices, count, n);
    return count;
}

private static void squarePermutations(int[] remaining, int[] indices, int& count, int n) {
    if (remaining.length == 0) {
        count++;
        return;
    }

    for (int i = 0; i < remaining.length; i++) {
        int remainingIndex = indices[i];
        int next = remainingIndex + 1;
        while (next < n) {
            int sum = A[remainingIndex] + A[next];
            if (sum % 1 == 0) {
                swap(remaining, remainingIndex, next);
                indices[next] = next;
                squarePermutations(remaining, indices, count, n);
                indices[next] = remainingIndex;
                swap(remaining, remainingIndex, next);
                break;
            }
            next++;
        }
    }
}

private static void swap(int[] array, int i, int j) {
    int temp = array[i];
    array[i] = array[j];
    array[j] = temp;
}
