import static java.lang.Math.sqrt;

import java.util.Arrays;

public static int squarePermutations(int[] A) {
    int[] freq = new int[100];
    for (int a : A) freq[a]++;

    int count = 0;
    int currentSquares = 100;
    int remainingSquares = 0;

    for (int i = 0; i < A.length; i++) {
        int nextSquareIndex = (int) Math.floor(sqrt((long) A[i] * (long) A[i + 1]));
        if (!freq[nextSquareIndex]-- || freq[i + 1]-- == 0) {
            return 0;
        }
        if (! freq[nextSquareIndex]) remainingSquares++;
        currentSquares = nextSquareIndex * nextSquareIndex;
    }

    int permutations = 1;
    while (remainingSquares > 0) {
        if (remainingSquares % 2 == 0) {
            permutations *= 2;
        }
        remainingSquares /= 2;
    }

    return permutations * currentSquares * currentSquares;
}
