public static int squarePermutations(int[] A) {
    // Check if the input array has less than 2 elements
    if (A.length < 2) {
        return 0;
    }

    // Check if all elements in the array are perfect squares
    for (int num : A) {
        if (!isPerfectSquare(num)) {
            return 0;
        }
    }

    // Calculate the number of square permutations
    return numPermutations(A);
}

private static boolean isPerfectSquare(int num) {
    int sqrt = (int) Math.sqrt(num);
    return sqrt * sqrt == num;
}

private static int numPermutations(int[] A) {
    // Check if the array is a permutation of constants (1, 4, 9, 16, ...)
    for (int i = 0; i < A.length - 1; i++) {
        if (A[i] % 4 != A[i + 1] % 4) {
            return 0;
        }
    }

    // Recursively count the number of valid square permutations
    if (A[0] % 4 == 0 || A[A.length - 1] % 4 == 0) {
        return numPermutations(A);
    }

    return 0;
}
