    for (int i = 1; i < length; i++) {
        ArrayList<ArrayList<Integer>> newDp = new ArrayList<>();
        for (int j = 0; j < dp.size(); j++) {
            int num = dp.get(j).get(dp.get(j).size() - 1);
            ArrayList<Integer> newNumList = new ArrayList<>(dp.get(j)) {{
                add(num + A[i]);
            }};
            int addIndex = newNumList.stream()
                    .filter(num -> num * num == A[i] + num)
                    .findAny()
                    .orElse(-1);

            if (addIndex != -1) {
                newNumList.set(addIndex, num);
                newDp.add(newNumList);
            } else {
                newDp.add(dp.get(j));
            }
        }
        dp = newDp;
    }

    return dp.size();
