public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0] == null || mat[0].length == 0) {
        return new int[0];
    }

    List<Integer> result = new ArrayList<>();
    int rows = mat.length;
    int cols = mat[0].length;
    int left = 0, right = cols - 1, top = 0, bottom = rows - 1;

    while (result.size() < rows * cols) {
        // Add top row from left to right
        for (int i = left; i <= right && result.size() < rows * cols; i++) {
            result.add(mat[top][i]);
            top++;
        }

        // Add rightmost column from top to bottom
        if (left <= right && result.size() < rows * cols) {
            for (int i = top; i <= bottom && result.size() < rows * cols; i++) {
                result.add(mat[i][right]);
                right--;
            }
        }

        // Move diagonally left upwards
        if (top < bottom && left <= right && result.size() < rows * cols) {
            for (int i = right; i >= left && result.size() < rows * cols; i--) {
                result.add(mat[bottom][i]);
                bottom--;
            }
        }

        // Move diagonally right downwards
        if (top <= bottom && left < right && result.size() < rows * cols) {
            for (int i = left; i <= right && result.size() < rows * cols; i++) {
                result.add(mat[top][i]);
                top++;
            }
        }

        // Move to the next diagonal
        left++;
        right--;
        top++;
        bottom--;
    }

    int[] resultArray = new int[result.size()];
    for (int i = 0; i < resultArray.length; i++) {
        resultArray[i] = result.get(i);
    }

    return resultArray;
}
