        ArrayList<Integer> list = new ArrayList<>();
        int rows = mat.length;
        int cols = mat[0].length;
        int totalDiagonals = rows + cols - 1;

        for (int i = 0; i <= totalDiagonals; ++i) {
            int k = i < rows ? i : rows - 1;
            int j = i < cols ? i : cols - 1;

            while (k >= 0 && j >= 0) {
                list.add(mat[k][j]);
                k--;
                j--;
            }
        }

        return list.stream().mapToInt(i -> i).toArray();
    }

