        if (dir == 0) {
            // Move up
            if (col == n - 1) {
                // Move to the next row
                row++;
            } else {
                col++;
            }
        } else {
            // Move down
            if (row == n - 1) {
                // Move to the next column
                col++;
            } else {
                row++;
            }
        }
        // Change direction when reaching the edge of the matrix
        if (row == 0 || col == 0 || row == n - 1 || col == n - 1) {
            dir = (dir + 1) % 2;
        }
    }
    return result;
}
