    int rows = mat.length, cols = mat[0].length, len = rows + cols - 1;
    int[] result = new int[len];
    int i = 0, j = 0;
    for (int diagonal = 0; diagonal <= len - 1; diagonal++) {
        for (int k = Math.min(diagonal, rows - i - 1); k >= Math.max(0, diagonal - cols + j); k--) {
            result[diagonal] = mat[i][k];
            i++;
            j++;
        }
        if (diagonal == rows - 1) i--;
    }
    return result;
}
