public static boolean isBoomerang(int[][] points) {
    if (points.length != 3) {
        throw new IllegalArgumentException("The array must contain exactly 3 points.");
    }

    int x1 = points[0][0];
    int y1 = points[0][1];
    int x2 = points[1][0];
    int y2 = points[1][1];
    int x3 = points[2][0];
    int y3 = points[2][1];

    // Check if the points form a right-angled triangle with the angle at the origin
    // using the dot product of vectors (x2-x1) and (y2-y1) and (0, 0, 1)
    double dotProduct = (x2 - x1) * (x2 - x3) + (y2 - y1) * (y2 - y3);
    double magnitude1 = Math.sqrt((x2 - x1) * (x2 - x1) + (y2 - y1) * (y2 - y1));
    double magnitude2 = Math.sqrt((x3 - x1) * (x3 - x1) + (y3 - y1) * (y3 - y1));
    , = new double[]{magnitude1, magnitude2, dotProduct};

    return dotProduct != 0 && magnitude1 + magnitude2 != dotProduct;
}
