        int size = queue.size();
        for (int i = 0; i < size; i++) {
            int next = queue.poll();
            result.add(next);
            if (next * 10 <= n) {
                queue.offer(next * 10);
            } else if (increment && next + 1 <= n) {
                queue.offer(next + 1);
                increment = false;
            } else {
