import java.util.ArrayList;
import java.util.List;

public class LexicalOrderSolver {
    public static List<Integer> lexicalOrder(int n) {
        List<Integer> result = new ArrayList<>();
        dfs("", n, result);
        return result;
    }

    private static void dfs(String current, int n, List<Integer> result) {
        if (current.length() > n) {
            return;
        }
        if (result.size() > n) {
            return;
        }
        if (current.length() == n) {
            result.add(Integer.parseInt(current));
            return;
        }

        // Include current number to result
        result.add(Integer.parseInt(current));

        for (char i = '0'; i <= '9'; i++) {
            dfs(current + i, n, result);
        }
    }

    public static void main(String[] args) {
        List<Integer> result = lexicalOrder(13);
        System.out.println(result); // Expected output: [1, 10, 11, 12, 13, 2, 3, 4, 5, 6, 7, 8, 9]
    }
}
