import java.lang.Math;
import java.util.ArrayList;
import java.util.List;

public class LexicalOrder {

    public List<Integer> lexicalOrder(int n) {
        List<Integer> result = new ArrayList<>();

        // Start generating numbers in lexicographical order
        for (int i = 1; i <= 9; i++) {
            generateNumbers(i, n, result);
        }
        return result;
    }

    // Helper method to generate numbers in lexicographical order
    void generateNumbers(int number, int n, List<Integer> result) {
        if (number > n) return;
        result.add(number);
        for (int i = 0; i <= 9; i++) {
            int nextNumber = number * 10 + i;
            if (nextNumber > n) return;
            generateNumbers(nextNumber, n, result);
        }
    }

    public static void main(String[] args) {
        LexicalOrder order = new LexicalOrder();
        List<Integer> result = order.lexicalOrder(13);
        System.out.println(result); // Expected output: [1, 10, 11, 12, 13, 2, 3, 4, 5, 6, 7, 8, 9]
    }
}
```

