```java
import java.lang.Math;

public class MinPerfectSquareSum {
    /**
     * Finds the minimum number of perfect square numbers that sum up to n.
     * 
     * @param n The target integer.
     * @return The minimum number of perfect square numbers.
     */
    public static int minPerfectSquareSum(int n) {
        int count = 0;
        while (n > 0) {
            n -= Math.pow(Math.floor(Math.sqrt(n)), 2);
            count++;
        }
        return count;
    }
}
