public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }

    int[] dp = new int[n + 1];
    Arrays.fill(dp, n); // Initialize the dp array with the maximum possible value

    dp[0] = 0; // Base case: no perfect square sum is needed for 0

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], 1 + dp[i - j * j]);
        }
    }

    return dp[n];
}
